    /**
     * Tests creating a new PriceBook.
     *
     * @return    PriceBook
     */
    public PriceBook testCreate() throws Throwable {
    PriceBook entity = null;

    LOGGER.info( "PriceBookTest:testCreate()" );
    LOGGER.info( "-- Attempting to create a PriceBook");

    StringBuilder msg = new StringBuilder( "-- Failed to create a PriceBook" );

    try {
        entity = service.createPriceBook( generateNewCommand() );
        assertNotNull( entity, msg.toString() );

        theId = entity.getPriceBookId();
        assertNotNull( theId, msg.toString() + " Contains a null primary key" );

        LOGGER.info( "-- Successfully created a PriceBook with primary key" + theId );
    }
    catch (Exception e)  {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + entity );

        throw e;
    }
    return entity;
}

