    /**
     * Tests getting all PriceBooks.
     *
     * @return    Collection
     */
    public List<PriceBook> testGetAll() throws Throwable {
    LOGGER.info( "PriceBookTest:testGetAll() - Retrieving Collection of PriceBooks:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all PriceBook : " );
    List<PriceBook> collection  = null;

    try {
        // call the static get method on the PriceBookService
        collection = service.getAllPriceBook();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            PriceBook currEntity  = null;
            Iterator<PriceBook> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getPriceBookId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

